package promql

import (
	"math"
	"testing"
	"time"
)

func TestAtan2ScalarTmp(t *testing.T) {
	test, err := NewTest(t, "")
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		query string
		want  float64
	}{
		{"1 atan2 2", math.Atan2(1, 2)},
		{"2 atan2 1", math.Atan2(2, 1)},
	} {
		q, err := test.QueryEngine().NewInstantQuery(test.Queryable(), tc.query, time.Unix(0, 0))
		if err != nil {
			t.Fatal(err)
		}
		res := q.Exec(test.Context())
		if res.Err != nil {
			t.Fatal(res.Err)
		}
		got, ok := res.Value.(Scalar)
		if !ok {
			t.Fatalf("expected scalar, got %T", res.Value)
		}
		if got.V != tc.want {
			t.Fatalf("%s: got %v, want %v", tc.query, got.V, tc.want)
		}
		q.Close()
	}
}

